 const filtered=state.servers.filter(s=>{const disk=diskHealth(s);return (!query||[s.name,s.host,s.p2pHost,s.hostGroup].some(value=>String(value||'').toLocaleLowerCase().includes(query)))&&(serverView.connection==='all'||serverConnectionState(s)===serverView.connection)&&(serverView.disk==='all'||serverView.disk==='alert'&&['warning','critical'].includes(disk.severity)||serverView.disk==='stale'&&disk.stale||serverView.disk===disk.severity)});
 filtered.sort((a,b)=>(serverView.sort==='created'?timestamp(b.createdAt)-timestamp(a.createdAt):serverView.sort==='host'?compare(a.host,b.host):compare(a.name,b.name))||compare(a.name,b.name)||compare(a.host,b.host)||compare(a.id,b.id));
 const pages=Math.max(1,Math.ceil(filtered.length/serverView.pageSize)),page=Math.max(1,Math.min(pages,serverView.page)),start=(page-1)*serverView.pageSize;
 return {filtered,items:filtered.slice(start,start+serverView.pageSize),page,pages,start,total:filtered.length};
