function updateServerFilters(){serverView.query=$('#serverSearch').value;serverView.connection=$('#serverConnectionFilter').value;serverView.disk=$('#serverDiskFilter').value;serverView.sort=$('#serverSort').value;const size=Number($('#serverPageSize').value);serverView.pageSize=[10,20,50].includes(size)?size:10;serverView.page=1;renderServerInventory()}
