function clearServerSelection(){if(serverBatchPending)return;selectedServerIds.clear();syncServerSelectionUI()}
function serverSelectionScope(servers){const visible=new Set(serverInventory().items.map(s=>s.id)),hidden=servers.filter(s=>!visible.has(s.id)).length;return {hidden,text:`共 ${servers.length} 台${hidden?`（其中 ${hidden} 台不在当前页）`:''}`,names:servers.map(s=>`${s.name} (${s.host})${visible.has(s.id)?'':' [不在当前页]'}`).join('\n')}}
