 pruneServerSelection();const selected=selectedServers(),page=serverInventory().items,pageSelected=page.filter(s=>selectedServerIds.has(s.id)).length,hidden=selected.length-pageSelected,hasLocal=selected.some(s=>s.host==='local'||s.host==='localhost-local'),hasLocked=selected.some(s=>serverLocked(s.id)),selectAll=$('#selectAllServers'),trust=$('#batchTrustServers'),remove=$('#batchDeleteServers'),overLimit=selected.length>100,disabled=!!serverBatchPending||serverActionRequests.size>0||!selected.length||overLimit;
