 trust.disabled=disabled||hasLocal;trust.title=overLimit?'单次最多操作 100 台':hasLocal?'本机服务器不需要信任 SSH 主机密钥':'';trust.textContent=serverBatchPending==='trust'?'信任中…':'批量信任';
