 $('#serverResultCount').textContent=inventory.total?`显示 ${inventory.start+1}–${inventory.start+inventory.items.length} / ${inventory.total} 台${inventory.total!==state.servers.length?`（全部 ${state.servers.length} 台）`:''}`:'显示 0 台';
