function nodeRecoveryAction(e,n){if(!['unreachable','recovering'].includes(n.status)&&!n.recoveryError&&!n.privateStateError)return '';const recovering=n.status==='recovering'||recoveryRequests.has(n.id),miningBusy=e.miningStatus==='updating'||minerRequests.has(e.id),disabled=miningBusy||e.status!=='running'||recovering;return `<button type="button" class="action secondary node-recover" onclick="recoverNode('${e.id}','${n.id}')" ${disabled?'disabled':''} title="${e.status!=='running'?'仅运行中的实验支持单节点恢复':miningBusy?'请等待矿工配置调整完成':'保留现有数据，检查进程并恢复连接'}">${recovering?'恢复中…':n.recoveryError?'重试恢复':'恢复节点'}</button>`}
