function experimentDetail(e){const nodes=e.nodes||[],hasUnavailable=nodes.some(n=>['unreachable','recovering'].includes(n.status)||n.privateStateError||n.recoveryError);return `<div class="row experiment-detail" data-experiment="${e.id}"><div class="row-title"><b>${esc(e.name)}</b>${status(e.status)}</div><div class="meta"><span>${experimentNodeCount(e)} 个节点</span><span>${esc(e.topology)}</span><span>Network ID ${e.networkId}</span><span>${new Date(e.createdAt).toLocaleString()}</span>${e.recoveryArtifactSha?`<span title="单节点恢复首选运行包 SHA-256：${esc(e.recoveryArtifactSha)}；不会自动重启其他节点">首选恢复包 ${esc(short(e.recoveryArtifactSha,12))}</span>`:''}</div>${experimentActions(e)}<details data-detail-key="experiment:${e.id}:miners"><summary>矿工配置 · ${configuredMinerCount(e)} 个</summary>${minerConfiguration(e)}</details>${hasUnavailable?'<p class="node-recovery-hint">节点不可达或隐私状态异常时可单独恢复；保留原有链与账户数据，不重新部署实验，也不重发交易。服务器离线时，请先恢复服务器与 SSH 连接。</p>':''}<h3 class="workspace-node-heading">节点状态 <small>${nodes.length} 个节点</small></h3><div class="node-list" tabindex="0" aria-label="实验节点状态列表">${nodes.map(n=>`<div class="node-line"><span class="node-identity">${esc(n.name)} · ${status(n.status,'node')}${nodeMiningLabel(e,n)}</span><span>区块 ${n.block||0}</span><span>${n.peers||0} peers</span><code title="${esc(n.account||'')}">${esc(short(n.account||'无账户',22))}</code><div class="node-line-action">${nodeRecoveryAction(e,n)}</div>${n.stateError||n.privateStateError||n.recoveryError||n.recoveryWarning||n.runtimeSha?`<div class="node-line-feedback">${nodeRuntimeMetadata(n)}${nodeRecoveryMessages(n)}</div>`:''}</div>`).join('')||'<span class="empty compact">尚未部署节点</span>'}</div>${errorDetails(`experiment:${e.id}:error`,'实验操作异常 · 查看详情',e.error)}</div>`}
function experimentSummary(e){const nodes=e.nodes||[],running=nodes.filter(n=>n.status==='running').length,maxBlock=nodes.reduce((n,x)=>Math.max(n,Number(x.block||0)),0),peers=nodes.reduce((n,x)=>n+Number(x.peers||0),0);return `<div class="overview-experiment"><div class="row-title"><b>${esc(e.name)}</b>${status(e.status)}</div><div class="experiment-stats"><div><b>${running}/${nodes.length}</b><span>节点在线</span></div><div><b>${maxBlock}</b><span>最高区块</span></div><div><b>${peers}</b><span>Peer 总数</span></div></div><div class="meta">${miningHealth(e)}</div><div class="meta"><span>${esc(e.topology)}</span><span>${new Date(e.createdAt).toLocaleString()}</span></div>${e.miningStatus==='updating'?'<p class="miner-config-progress" role="status">正在调整矿工配置…</p>':e.miningError?'<p class="miner-health-warning">矿工配置未完全生效，请管理实验并检查节点。</p>':''}${e.error?`<p class="status failed breakable">${esc(short(e.error,100))}</p>`:''}<button class="action secondary" onclick="showExperiment('${e.id}')">管理实验</button></div>`}
