 const x=systemInfo(s.systemInfo),cpus=Number(x.cpus||0),memory=Number(x.memory_kb||0),available=Number(x.memory_available_kb||0),disk=diskHealth(s),locked=serverLocked(s.id),stale=!!s.lastError||s.status==='error';
