async function saveBatchServerForm(event){
 event.preventDefault();if(serverFormPending)return;const form=event.currentTarget;if(!form.reportValidity())return;const values=Object.fromEntries(new FormData(form));values.hosts=[...new Set(values.hosts.split(/[\s,;]+/).map(x=>x.trim()).filter(Boolean))];values.port=Number(values.port);
 if(!values.hosts.length||values.hosts.length>100){showServerEditorError('请填写 1–100 台服务器');return}
 setServerFormPending(true);$('#serverEditorError').hidden=true;try{const created=await api('/servers/batch',{method:'POST',body:JSON.stringify(values)});form.reset();$('#serverEditor').close();toast(`已添加 ${created.length} 台服务器`);await refreshSavedServers('批量创建已成功')}catch(error){showServerEditorError(error.message)}finally{setServerFormPending(false)}
}
function openServerHostGroup(){
 const servers=selectedServers();if(serverBatchPending||serverActionRequests.size||!servers.length||servers.length>100)return;serverGroupTargets=servers.map(s=>({...s}));const scope=serverSelectionScope(servers);
 $('#serverGroupScope').textContent=`${scope.text}\n${scope.names}`;const groups=new Set(servers.map(s=>s.hostGroup||''));$('#serverGroupInput').value=groups.size===1?[...groups][0]:'';$('#serverGroupError').hidden=true;$('#serverHostGroupDialog').showModal();
}
function closeServerHostGroup(){if(serverBatchPending!=='group')$('#serverHostGroupDialog').close()}
async function saveServerHostGroup(event){
 event.preventDefault();if(serverBatchPending||!serverGroupTargets.length)return;const hostGroup=$('#serverGroupInput').value.trim(),scope=serverSelectionScope(serverGroupTargets);
 if([...hostGroup].length>80||/[\u0000-\u001f\u007f]/.test(hostGroup)){$('#serverGroupError').textContent='宿主机标注最多 80 个字符，不能包含控制字符';$('#serverGroupError').hidden=false;return}
 if(!confirm(`${hostGroup?'设置宿主机标注为“'+hostGroup+'”':'清除宿主机标注'}，${scope.text}：\n\n${scope.names}\n\n仅更新手动标注，不会自动切换现有实验的矿工角色。确认保存？`))return;
 const ids=serverGroupTargets.map(s=>s.id);serverBatchPending='group';syncServerSelectionUI();for(const control of document.querySelectorAll('#serverHostGroupDialog input,#serverHostGroupDialog button'))control.disabled=true;
 try{const result=await api('/servers/batch/host-group',{method:'POST',body:JSON.stringify({ids,hostGroup})});$('#serverHostGroupDialog').close();serverGroupTargets=[];toast(`已更新 ${result.updated} 台服务器的宿主机标注`);await refreshSavedServers('宿主机标注保存已成功')}catch(error){$('#serverGroupError').textContent=error.message;$('#serverGroupError').hidden=false}finally{serverBatchPending='';for(const control of document.querySelectorAll('#serverHostGroupDialog input,#serverHostGroupDialog button'))control.disabled=false;syncServerSelectionUI()}
}
async function deleteServer(id){const server=state.servers.find(s=>s.id===id);if(!server||serverBatchPending||serverActionRequests.has(id)||serverLocked(id)||!confirm(`确定删除服务器配置“${server.name}”吗？\n\n只删除 Lab 中的配置，不会删除远端文件；历史实验记录会保留。`))return;serverActionRequests.add(id);syncServerSelectionUI();try{await api(`/servers/${encodeURIComponent(id)}`,{method:'DELETE'});selectedServerIds.delete(id);if($('#serverForm')?.elements.serverId.value===id)resetServerForm();toast('服务器配置已删除');await refreshSavedServers('服务器配置已删除')}catch(error){toast(error.message)}finally{serverActionRequests.delete(id);syncServerSelectionUI()}}
function showExperiment(id){experimentView.query='';experimentView.status='';experimentView.selected=id;experimentView.page=Math.floor(Math.max(0,newestFirst(state.experiments).findIndex(e=>e.id===id))/experimentView.size)+1;$('#experimentSearch').value='';$('#experimentStatusFilter').value='';document.querySelectorAll('nav button,.tab').forEach(x=>x.classList.remove('active'));document.querySelector('nav button[data-tab="experiments"]').classList.add('active');$('#experiments').classList.add('active');render();requestAnimationFrame(()=>document.querySelector(`[data-experiment="${id}"]`)?.scrollIntoView({behavior:'smooth',block:'start'}))}
async function experiment(id,action){
 const e=state.experiments.find(x=>x.id===id);if(!e||experimentBusy(e))return;
 if(action==='deploy'&&!canFreshDeploy(e)||action==='resume'&&!canResume(e)||action==='stop'&&!canStopExperiment(e))return;
 if(!['deploy','resume','stop'].includes(action))return;
 if(action==='stop'&&!confirm(`停止实验“${e.name}”？\n\n自动负载将停止新增投递；尚未开始的排队交易会取消。执行中或等待确认的交易将标为待核验，需检查链上结果，不能重复发送。随后停止实验节点。`))return;
 if(action==='resume'&&!confirm(`按原目录恢复实验“${e.name}”？\n\n使用已保存的节点清单和原运行包 SHA，保留链数据与账户。待核验交易继续保留占用，不会重新部署、初始化账户或重发交易。`))return;
 lifecycleRequests.add(id);render();try{const result=await api(`/experiments/${id}/${action}`,{method:'POST'});if(result?.status)e.status=result.status;toast('任务已进入后台');await refresh()}catch(error){toast(error.message)}finally{lifecycleRequests.delete(id);render()}
}
async function deleteExperiment(id){const e=state.experiments.find(e=>e.id===id);if(!e||experimentActive(e)||experimentBusy(e))return;const name=e.name||id;if(!confirm(`确定删除实验“${name}”吗？\n\n该实验的交易、自动负载、账户快照和事件记录也会永久删除。`))return;try{await api(`/experiments/${id}`,{method:'DELETE'});toast('实验及关联记录已删除');await refresh()}catch(e){toast(e.message)}}
async function queryNode(experimentId,nodeId){try{toast('正在查询节点链上状态…');await api(`/experiments/${experimentId}/nodes/${nodeId}/state`,{method:'POST'});await refresh();toast('账户状态已更新')}catch(e){toast(e.message)}}
async function recoverNode(experimentId,nodeId){
 const experiment=state.experiments.find(e=>e.id===experimentId),node=experiment?.nodes?.find(n=>n.id===nodeId);
 if(!node||experiment.status!=='running'||experiment.miningStatus==='updating'||minerRequests.has(experimentId)||node.status==='recovering'||(node.status!=='unreachable'&&!node.recoveryError&&!node.privateStateError)||recoveryRequests.has(nodeId))return;
 if(!confirm(`恢复实验“${experiment.name}”中的 ${node.name}？\n\n将检查现有进程，使用${experiment.recoveryArtifactSha?'已配置的恢复运行包':'本实验原有运行包'}和原有数据恢复该节点及其连接。${experiment.recoveryArtifactSha?'\n需要应用恢复包时，会仅重启当前节点，不重启其他节点。':''}\n\n不会清空链数据、重新创建账户或重发交易。若服务器本身离线，请先恢复服务器与 SSH 连接。`))return;
 recoveryRequests.add(nodeId);render();
 try{await api(`/experiments/${experimentId}/nodes/${nodeId}/recover`,{method:'POST'});toast('恢复任务已启动，节点状态和结果将自动更新');await refresh()}catch(e){toast(e.message);await refresh()}finally{recoveryRequests.delete(nodeId);render()}
}
async function initializeAllAccounts(){const experimentId=$('#experimentSelect').value,e=state.experiments.find(x=>x.id===experimentId);if(!e||e.status!=='running')return;const active=state.transactions.filter(t=>t.experimentId===experimentId&&activeTx(t)),busyNodes=new Set(active.flatMap(t=>[t.fromNode,t.toNode].filter(Boolean))),eligible=(e.nodes||[]).filter(n=>n.status==='running'&&!n.privateStateError&&!privateAccountInitialized(experimentId,n)&&!busyNodes.has(n.id));if(!eligible.length){toast('当前没有可初始化的空闲节点');return}if(!confirm(`将在实验“${e.name}”中，为 ${eligible.length} 个节点各排入 1 笔 CreateAccount。\n\n这会初始化隐私账户、产生真实链上交易并计入实验统计；不会执行 Mint。已初始化、正忙或隐私状态异常的节点会自动跳过。`))return;const button=$('#initializeAccounts');if(button){button.disabled=true;button.textContent='正在排队…'}try{const result=await api(`/experiments/${experimentId}/initialize-accounts`,{method:'POST'}),details=[`已排队 ${result.queued} 笔`];if(result.alreadyInitialized)details.push(`已初始化 ${result.alreadyInitialized}`);if(result.busy)details.push(`正忙 ${result.busy}`);if(result.unavailable)details.push(`不可用 ${result.unavailable}`);toast(details.join(' · '));await refresh()}catch(x){toast(x.message);await refresh()}}
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{document.querySelectorAll('nav button,.tab').forEach(x=>x.classList.remove('active'));b.classList.add('active');$('#'+b.dataset.tab).classList.add('active');render()});
