$('#consoleForm').onsubmit=async e=>{e.preventDefault();const button=$('#executeConsole'),result=$('.console-result'),output=$('#consoleOutput'),meta=$('#consoleMeta'),body=Object.fromEntries(new FormData(e.target));button.disabled=true;button.textContent='执行中…';result.classList.remove('error');output.textContent='正在等待节点返回结果…';meta.textContent='';try{const value=await api('/console/execute',{method:'POST',body:JSON.stringify(body)});output.textContent=value.output||'(命令执行成功，没有输出)';meta.textContent=`${value.nodeName} · ${value.durationMs} ms`}catch(x){result.classList.add('error');output.textContent=[x.payload?.output,x.message].filter(Boolean).join('\n')||'执行失败';meta.textContent=x.payload?.nodeName?`${x.payload.nodeName} · ${x.payload.durationMs} ms`:'执行失败'}finally{button.disabled=false;button.textContent='执行命令'}};
